5:/**
6: * Tax is applied after ALL line and invoice discounts.
7: * 'line': independently half-even round each netCents * taxBps / 10000.
8: * 'invoice': group lines by taxBps; independently half-even round each group's
9: * signed exact tax sum, then distribute that group tax using signed largest
10: * remainders (see allocation.js). Credit lines belong to their rate's group,
11: * even if the group's net basis is zero or negative. Do not group different
12: * rates together or allocate group tax proportionally to a net group total.
13: * Return taxes in original line order. Invoice tax is the sum of line taxes.
14: */
15:function calculateTaxes(lines, taxMode) {
16:  const numerators = lines.map(line => BigInt(line.netCents) * BigInt(line.taxBps));
17:  if (taxMode === 'line') return numerators.map(value => roundRatio(value, 10000n));
18:  const groups = new Map();
19:  lines.forEach((line, index) => {
20:    if (!groups.has(line.taxBps)) groups.set(line.taxBps, []);
21:    groups.get(line.taxBps).push(index);
22:  });
23:  const taxes = lines.map(() => 0);
24:  for (const indexes of groups.values()) {
25:    const ideals = indexes.map(index => numerators[index]);
26:    const groupTax = roundRatio(ideals.reduce((sum, value) => sum + value, 0n), 10000n);
27:    const allocated = distribute(groupTax, ideals, 10000n);
28:    indexes.forEach((index, offset) => { taxes[index] = allocated[offset]; });
29:  }
30:  return taxes;
31:}
32:
